const wm_anim_program *wm_anim_program_find(const char *source_label) {
    size_t i;
    if (!source_label) return 0;
    for (i = 0; i < sizeof(programs)/sizeof(programs[0]); ++i)
        if (__builtin_strcmp(programs[i].source_label, source_label) == 0)
            return &programs[i];
    return 0;
}
